// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 value, bytes calldata data) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != c.owner());
        vm.assume(value == 0);
        vm.assume(data.length <= 1024);

        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(address(0xdead), value, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
